import{_ as t,o as e,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const p=JSON.parse('{"title":"按数据链路排查运行问题","description":"从来源、数据点、计算、报警、版本、部署到入口与历史逐段定位问题，避免反复重建或把开发结果当正式运行。","frontmatter":{"title":"按数据链路排查运行问题","description":"从来源、数据点、计算、报警、版本、部署到入口与历史逐段定位问题，避免反复重建或把开发结果当正式运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/runtime-data-troubleshooting.md","filePath":"zh/使用指南/按数据链路排查运行问题.md"}'),i={name:"zh/guide/runtime-data-troubleshooting.md"};function h(l,a,o,n,s,u){return e(),d("div",null,[...a[0]||(a[0]=[r('<h1 id="按数据链路排查运行问题" tabindex="-1">按数据链路排查运行问题 <a class="header-anchor" href="#按数据链路排查运行问题" aria-label="Permalink to &quot;按数据链路排查运行问题&quot;">​</a></h1><p>数据来源、工程配置、开发验证、运行部署和用户页面是不同环节。遇到“AI 改好了但线上没变化”，先定位断在哪一段，不一次性重做全部配置。</p><p>开始前记录组织、工程、运行环境、模式或版本、发生时间与具体对象。只读检查优先；重启、替换、停用和删除先取得授权并安排影响。</p><h2 id="_1-先确认在看哪套内容" tabindex="-1">1. 先确认在看哪套内容 <a class="header-anchor" href="#_1-先确认在看哪套内容" aria-label="Permalink to &quot;1. 先确认在看哪套内容&quot;">​</a></h2><ul><li>编辑器、数据中心和开发预览主要用于当前开发配置。</li><li>生产部署使用所选工程版本；开发模式部署也使用提交时构建的快照，不是浏览器实时源码。</li><li>修改和保存配置不会自动更新旧部署，“重新部署”也不自动采用最新内容。</li></ul><p>在部署详情核对实际模式、版本和环境，再检查是否确实执行了<a href="/induframe-docs/zh/guide/project-releases.html">新版本发布</a>与更新部署。</p><h2 id="_2-从源头逐段检查" tabindex="-1">2. 从源头逐段检查 <a class="header-anchor" href="#_2-从源头逐段检查" aria-label="Permalink to &quot;2. 从源头逐段检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>到哪里查</th><th>先看什么</th></tr></thead><tbody><tr><td>数据来源</td><td>数据中心 → 接入源或工业采集</td><td>正确连接、查询或订阅、授权、设备/服务状态与真实样本</td></tr><tr><td>数据点</td><td>数据中心 → 数据点 → 查看详情</td><td>完整路径、来源、类型、质量、值来源和时间</td></tr><tr><td>计算</td><td>数据中心 → 计算单元</td><td>输入点、脚本、输出、触发、启用；调试是否保存后进行</td></tr><tr><td>报警</td><td>数据中心 → 报警单元</td><td>输入点、类型、单位、阈值、延时、死区、恢复条件与启用</td></tr><tr><td>版本</td><td>工程管理 → 发布工程</td><td>本次配置是否进入构建成功的工程版本</td></tr><tr><td>部署</td><td>运维管理 → 工程部署</td><td>使用的模式与版本、节点、引擎健康及任务进度</td></tr><tr><td>页面访问</td><td>环境访问入口或节点直连</td><td>实际开关、地址、入口节点、证书和工程用户角色</td></tr><tr><td>历史</td><td>数据中心 → 历史存储及对应运行服务</td><td>继承策略、目标、样本触发、保留期和查询时间范围</td></tr></tbody></table><p>当前值有数字，但来自默认值、配置预览或陈旧观测时，不能作为链路正常的证据。</p><h2 id="_3-常见现象怎样分流" tabindex="-1">3. 常见现象怎样分流 <a class="header-anchor" href="#_3-常见现象怎样分流" aria-label="Permalink to &quot;3. 常见现象怎样分流&quot;">​</a></h2><h3 id="sql-有结果-数据点没有" tabindex="-1">SQL 有结果，数据点没有 <a class="header-anchor" href="#sql-有结果-数据点没有" aria-label="Permalink to &quot;SQL 有结果，数据点没有&quot;">​</a></h3><p>回对应连接检查保存查询、输出配置及是否主动生成点。只运行一次 SQL 不会自动完成整条配置，见<a href="/induframe-docs/zh/guide/sql-datapoints.html">SQL 数据点</a>。</p><h3 id="计算试运行正确-输出点不变" tabindex="-1">计算试运行正确，输出点不变 <a class="header-anchor" href="#计算试运行正确-输出点不变" aria-label="Permalink to &quot;计算试运行正确，输出点不变&quot;">​</a></h3><p>试运行不写输出点。继续查实际运行部署、计算引擎、触发和输入更新，不为刷新值反复点试运行。</p><h3 id="数值越限-但没有看到现场报警" tabindex="-1">数值越限，但没有看到现场报警 <a class="header-anchor" href="#数值越限-但没有看到现场报警" aria-label="Permalink to &quot;数值越限，但没有看到现场报警&quot;">​</a></h3><p>先核对是否看同一环境的运行值、类型与单位，规则是否进入该部署，报警引擎是否健康，以及延时、死区和质量是否让判定暂停。</p><p>试算匹配不等于现场已经触发；没有新数据或输入质量异常时，也不能直接判断报警引擎故障。</p><h3 id="已有报警-但没有收到通知" tabindex="-1">已有报警，但没有收到通知 <a class="header-anchor" href="#已有报警-但没有收到通知" aria-label="Permalink to &quot;已有报警，但没有收到通知&quot;">​</a></h3><p>检查规则的通知继承或单独设置、渠道启用、认证、网络和发送结果。获准后单独测试渠道；通知测试不替代真实触发和恢复链路验证。</p><h3 id="页面正常-另一用户无数据" tabindex="-1">页面正常，另一用户无数据 <a class="header-anchor" href="#页面正常-另一用户无数据" aria-label="Permalink to &quot;页面正常，另一用户无数据&quot;">​</a></h3><p>核对工程用户与角色、点位调用权限及登录身份。开发人员的预览身份不等于普通运行用户，复制点路径不会授予权限。</p><h3 id="工程显示运行中-但地址打不开" tabindex="-1">工程显示运行中，但地址打不开 <a class="header-anchor" href="#工程显示运行中-但地址打不开" aria-label="Permalink to &quot;工程显示运行中，但地址打不开&quot;">​</a></h3><p>分别检查引擎健康、入口方式、入口节点、端口、路由、证书和网络。工程运行中与入口可访问不是同一状态。</p><h3 id="当前值有更新-却查不到历史" tabindex="-1">当前值有更新，却查不到历史 <a class="header-anchor" href="#当前值有更新-却查不到历史" aria-label="Permalink to &quot;当前值有更新，却查不到历史&quot;">​</a></h3><p>先查实际保存策略、来源与单点例外、部署内容、存储目标、样本写入和时间范围。历史不是自动备份，也不会把按需查询自动变成持续采样。</p><h2 id="_4-查看运维记录与有效观测" tabindex="-1">4. 查看运维记录与有效观测 <a class="header-anchor" href="#_4-查看运维记录与有效观测" aria-label="Permalink to &quot;4. 查看运维记录与有效观测&quot;">​</a></h2><p>到<a href="/induframe-docs/zh/guide/operations-records.html">运维记录</a>按对象、环境和时间筛选，区分已受理、执行中、完成及失败，阅读执行明细。</p><p>节点在线不等于所有驱动与运行资格都合格；旧的绿色状态不代表最新观测。加载失败或更新中断时，先重新读取，不反复提交操作。</p><h2 id="_5-不要用破坏性操作试错" tabindex="-1">5. 不要用破坏性操作试错 <a class="header-anchor" href="#_5-不要用破坏性操作试错" aria-label="Permalink to &quot;5. 不要用破坏性操作试错&quot;">​</a></h2><ul><li>不以重建基础服务、清库或删除环境刷新页面，它们可能清空数据。</li><li>活动报警未恢复时，不随意停用或删除规则，避免失去清警路径。</li><li>不靠关闭证书校验、共用管理员或分享密钥解决权限与连接问题。</li><li>不把删除开发源码、对话、点位或部署当作同一种“重置”。</li></ul><p>求助时提供对象、版本、环境、时间、错误和已核对步骤，敏感凭据留在安全渠道。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a> · <a href="/induframe-docs/zh/guide/data-flow-tutorial.html">联动教程</a> · <a href="/induframe-docs/zh/guide/environment-entry.html">访问入口</a>。</p>',32)])])}const _=t(i,[["render",h]]);export{p as __pageData,_ as default};
